//! Glyph data (REQ-RND-010, REQ-RND-020, REQ-RND-037; layer L4).
//!
//! A G0 or G2 glyph is 5 dots by 9 lines in the SAA5050 geometry, looked up
//! by Unicode code point. A G3 glyph is a full 12 half-dot line for every
//! line of the 12 by 10 and the 12 by 20 cell, with no rounding (decision
//! E.50). Glyph sets are data, replaceable without code changes:
//!
//! - `bedstead.rs` is generated by `cargo xtask glyphs` from
//!   `third_party/bedstead/bedstead-glyphs.txt`: Bedstead 3.261, the one
//!   bundled font (REQ-FNT-001, decision E.72).
//! - `g3.rs` is generated by the same command from `g3.txt`, which it draws
//!   from the project's own geometry (decision E.50).
//! - `required.txt`, generated by the same command from the character set
//!   tables, lists every character a glyph set must draw; a test reports
//!   the ones Bedstead lacks (REQ-FNT-001).
//!
//! A [`GlyphSet`] may also carry up to two fonts loaded at run time
//! (REQ-FNT-008): the font in use, then the user's font, each a table of
//! 12 by 10 glyphs the program supplies. A text character is drawn from the
//! first of them that has it, and otherwise from the bundled glyphs
//! (REQ-FNT-005).
//!
//! DRCS characters have no glyph here: the renderer draws them from the
//! patterns that travel with the grid (REQ-RND-038).

// Generated by `cargo xtask glyphs`.
#[rustfmt::skip]
#[cfg(feature = "bedstead")]
mod bedstead;
// Generated by `cargo xtask glyphs`.
#[rustfmt::skip]
mod g3;
pub mod conformance;

use crate::charset::{CharRef, CharSet, compose, to_unicode};
use crate::consts::{
    CELL_FIELD_LINES, CELL_HEIGHT, CELL_WIDTH, DIACRITIC_NONE, FONT_MAX_CHARACTERS, G3_CODES, G3_FIRST_CODE,
    GLYPH_LINES,
};
use crate::types::{DrcsCharacter, FontGlyph};
use conformance::{FONT_SET_COUNT, font_set_of};

/// One G3 glyph (REQ-RND-037): each line of the cell as 12 half-dots, bit
/// 11 the leftmost, top line first.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct G3Glyph {
    /// The 12 by 10 cell.
    pub small: [u16; CELL_FIELD_LINES],
    /// The 12 by 20 cell.
    pub large: [u16; CELL_HEIGHT],
}

impl G3Glyph {
    /// A glyph with no dots: 5/F, the unassigned positions, and codes
    /// outside the set (decision E.50).
    pub const BLANK: Self = Self { small: [0; CELL_FIELD_LINES], large: [0; CELL_HEIGHT] };
}

/// How the renderer draws a character (REQ-RND-016).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum CharClass {
    /// A G0 or G2 character: a 5 by 9 glyph, with rounding, underline and
    /// the font styles.
    Text,
    /// A G3 character, by its code (REQ-RND-037).
    G3(u8),
    /// A DRCS character, drawn from the grid's patterns (REQ-RND-038).
    Drcs(DrcsCharacter),
}

/// How a character is drawn.
#[must_use]
pub const fn class(character: CharRef) -> CharClass {
    match character.set {
        CharSet::G0(_) | CharSet::G2(_) => CharClass::Text,
        CharSet::G3 => CharClass::G3(character.code),
        CharSet::Drcs { table, subtable } => {
            CharClass::Drcs(DrcsCharacter { table, subtable, character: character.code })
        }
    }
}

/// One glyph: rows top to bottom, bit 4 the leftmost dot.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct GlyphEntry {
    /// The Unicode code point.
    pub code_point: u32,
    /// Nine rows of five dots.
    pub rows: [u8; GLYPH_LINES],
}

/// A glyph set: G0 and G2 entries sorted by code point, the G3 set, and
/// loaded fonts: the font in use, and the user's font for each character
/// set (REQ-FNT-005, decision E.75 item 6).
#[derive(Clone, Copy, Debug)]
pub struct GlyphSet<'a> {
    entries: &'static [GlyphEntry],
    /// Where the glyphs come from, for provenance records (REQ-GEN-012).
    pub provenance: &'static str,
    g3: &'static [G3Glyph; G3_CODES],
    /// Where the G3 glyphs come from (REQ-GEN-012, REQ-RND-037).
    pub g3_provenance: &'static str,
    in_use: Option<LoadedFont<'a>>,
    by_set: [Option<LoadedFont<'a>>; FONT_SET_COUNT],
}

/// Why a glyph table cannot be a loaded font (REQ-FNT-003, REQ-FNT-008).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum FontTableError {
    /// More than 1,024 glyphs.
    TooMany,
    /// The code points are not in strictly increasing order: unsorted or
    /// repeated.
    Order,
    /// A code point is not a Unicode scalar value.
    Code,
    /// A line has a dot beyond the 12 of the cell.
    Width,
    /// The glyphs are not all of one height, or a 12 by 10 glyph has lines
    /// beyond its tenth (decision E.77).
    Height,
}

/// A font loaded at run time (REQ-FNT-008): a table of 12 by 10 or 12 by 20
/// glyphs, all of one height (decision E.77), sorted by code point. The table comes from outside the library, so it is
/// checked for shape when the font is made
/// (`docs/spec/design/font-security.md` section 3.1).
#[derive(Clone, Copy, Debug)]
pub struct LoadedFont<'a> {
    glyphs: &'a [FontGlyph],
    dot_matrix: bool,
    tall: bool,
}

/// The right-hand pixel of each of a 12-pixel row's six pairs.
const PAIR_RIGHT_PIXELS: u16 = 0b0101_0101_0101;

/// A glyph of a loaded font, and whether the font is a doubled dot matrix,
/// which is rounded as Bedstead is (REQ-FNT-008, issue #209).
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub struct LoadedGlyph {
    /// The lines of 12 pixels, bit 11 the leftmost: the first ten of a 12
    /// by 10 glyph, or all twenty of a 12 by 20 glyph.
    pub rows: [u16; CELL_HEIGHT],
    /// The glyph is 12 by 20 and is drawn line for line (decision E.77).
    pub tall: bool,
    /// Every row of every glyph of its font is made of identical pixel
    /// pairs. Never true of a 12 by 20 font.
    pub dot_matrix: bool,
}

impl<'a> LoadedFont<'a> {
    /// The font of a table, after checking its shape.
    pub fn new(glyphs: &'a [FontGlyph]) -> Result<Self, FontTableError> {
        if glyphs.len() > FONT_MAX_CHARACTERS {
            return Err(FontTableError::TooMany);
        }
        if !glyphs.windows(2).all(|pair| matches!(pair, [a, b] if a.code_point < b.code_point)) {
            return Err(FontTableError::Order);
        }
        let tall = glyphs.first().is_some_and(|glyph| glyph.tall);
        for glyph in glyphs {
            if char::from_u32(glyph.code_point).is_none() {
                return Err(FontTableError::Code);
            }
            if glyph.rows.iter().any(|row| row >> CELL_WIDTH != 0) {
                return Err(FontTableError::Width);
            }
            let beyond = glyph.rows.get(glyph.lines().len()..).unwrap_or(&[]);
            if glyph.tall != tall || beyond.iter().any(|&row| row != 0) {
                return Err(FontTableError::Height);
            }
        }
        // A font converted from a 5- or 6-dot matrix (REQ-FNT-010) has
        // every pixel doubled; one drawn at half-dot resolution does not. A
        // 12 by 20 font is never rounded (decision E.77).
        let dot_matrix = !tall
            && !glyphs.is_empty()
            && glyphs.iter().all(|glyph| glyph.rows.iter().all(|row| (row ^ (row >> 1)) & PAIR_RIGHT_PIXELS == 0));
        Ok(Self { glyphs, dot_matrix, tall })
    }

    /// True when every row of every glyph is made of identical pixel
    /// pairs: a 5- or 6-dot matrix with each dot drawn two pixels wide,
    /// which the renderer rounds as the SAA5050 rounded its matrix
    /// (REQ-FNT-008, decision E.13).
    #[must_use]
    pub const fn is_dot_matrix(&self) -> bool {
        self.dot_matrix
    }

    /// Number of glyphs.
    #[must_use]
    pub const fn len(&self) -> usize {
        self.glyphs.len()
    }

    /// True when the font has no glyphs.
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.glyphs.is_empty()
    }

    /// True when the font's glyphs are 12 by 20 (decision E.77).
    #[must_use]
    pub const fn is_tall(&self) -> bool {
        self.tall
    }

    /// The glyph of a code point.
    #[must_use]
    pub fn lookup(&self, character: char) -> Option<FontGlyph> {
        let code_point = u32::from(character);
        self.glyphs
            .binary_search_by_key(&code_point, |glyph| glyph.code_point)
            .ok()
            .and_then(|index| self.glyphs.get(index))
            .copied()
    }
}

/// A visible placeholder for characters with no glyph (REQ-CHR-004): a
/// hollow box.
pub const PLACEHOLDER: [u8; GLYPH_LINES] = [0x1F, 0x11, 0x11, 0x11, 0x11, 0x11, 0x1F, 0x00, 0x00];

impl GlyphSet<'static> {
    #[cfg(feature = "bedstead")]
    /// Bedstead 3.261, the one bundled font (REQ-FNT-001, decision E.72).
    #[must_use]
    pub const fn bedstead() -> Self {
        Self::from_entries(&bedstead::GLYPHS, bedstead::PROVENANCE)
    }

    /// A glyph set over caller-supplied entries, which must be sorted by
    /// code point, with the generated G3 glyphs.
    #[must_use]
    pub const fn from_entries(entries: &'static [GlyphEntry], provenance: &'static str) -> Self {
        Self {
            entries,
            provenance,
            g3: &g3::G3,
            g3_provenance: g3::PROVENANCE,
            in_use: None,
            by_set: [None; FONT_SET_COUNT],
        }
    }
}

impl<'a> GlyphSet<'a> {
    /// The same set with loaded fonts (REQ-FNT-005): `in_use`, the font
    /// drawing the page, then for a character it lacks the user's font for
    /// the character's own set, by its place in `FONT_SETS`; the set's own
    /// glyphs come last.
    #[must_use]
    pub const fn with_fonts<'b>(
        self,
        in_use: Option<LoadedFont<'b>>,
        by_set: [Option<LoadedFont<'b>>; FONT_SET_COUNT],
    ) -> GlyphSet<'b>
    where
        'a: 'b,
    {
        GlyphSet {
            entries: self.entries,
            provenance: self.provenance,
            g3: self.g3,
            g3_provenance: self.g3_provenance,
            in_use,
            by_set,
        }
    }

    /// The same set without loaded fonts: the receiver's own drawing
    /// (REQ-FNT-001).
    #[must_use]
    pub const fn without_fonts(self) -> Self {
        Self { in_use: None, by_set: [None; FONT_SET_COUNT], ..self }
    }

    /// The set's own G0 and G2 glyphs, sorted by code point.
    #[cfg(test)]
    #[must_use]
    pub(crate) const fn entries(&self) -> &'static [GlyphEntry] {
        self.entries
    }

    /// True when a loaded font is set.
    #[must_use]
    pub fn has_fonts(&self) -> bool {
        self.in_use.is_some() || self.by_set.iter().any(Option::is_some)
    }

    /// The glyph of a G0 or G2 character from the loaded fonts: the
    /// font in use, then the user's font for the character's own set
    /// (REQ-FNT-005, REQ-FNT-008); `None` when neither has it, and the set's
    /// own glyphs draw it. A character with a diacritical
    /// mark is found by its precomposed form only; without one it falls to
    /// the set's own glyphs, which overlay the mark (decision E.26).
    #[must_use]
    pub fn loaded(&self, character: CharRef) -> Option<LoadedGlyph> {
        if !self.has_fonts() || !matches!(character.set, CharSet::G0(_) | CharSet::G2(_)) {
            return None;
        }
        let unicode = to_unicode(character);
        let wanted = match unicode.combining.filter(|_| character.diacritic != DIACRITIC_NONE) {
            Some(mark) => compose(unicode.base, mark)?,
            None => crate::charset::glyph_key(character),
        };
        let for_set = font_set_of(character.set).and_then(|place| self.by_set.get(place).copied().flatten());
        [self.in_use, for_set].into_iter().flatten().find_map(|font| {
            font.lookup(wanted).map(|glyph| LoadedGlyph {
                rows: glyph.rows,
                tall: glyph.tall,
                dot_matrix: font.dot_matrix,
            })
        })
    }

    /// The same set with other G3 glyphs, indexed by code minus 2/0
    /// (REQ-RND-020).
    #[must_use]
    pub const fn with_g3(self, g3: &'static [G3Glyph; G3_CODES], provenance: &'static str) -> Self {
        Self { g3, g3_provenance: provenance, ..self }
    }

    /// The glyph of a G3 code; a blank glyph outside 2/0 to 7/F.
    #[must_use]
    pub fn g3(&self, code: u8) -> &G3Glyph {
        code.checked_sub(G3_FIRST_CODE).and_then(|offset| self.g3.get(usize::from(offset))).unwrap_or(&G3Glyph::BLANK)
    }

    /// Number of glyphs.
    #[must_use]
    pub const fn len(&self) -> usize {
        self.entries.len()
    }

    /// True when the set has no glyphs.
    #[must_use]
    pub const fn is_empty(&self) -> bool {
        self.entries.is_empty()
    }

    /// The glyph of a code point.
    #[must_use]
    pub fn lookup(&self, character: char) -> Option<[u8; GLYPH_LINES]> {
        let code_point = u32::from(character);
        self.entries
            .binary_search_by_key(&code_point, |entry| entry.code_point)
            .ok()
            .and_then(|index| self.entries.get(index))
            .map(|entry| entry.rows)
    }

    /// The glyph of a G0 or G2 character, composing diacritical marks as
    /// decision E.26 describes (REQ-RND-014): a precomposed glyph if the set has one,
    /// otherwise the mark overlaid on the base. Missing glyphs give the
    /// placeholder; spaces give an empty glyph. The renderer draws G3
    /// characters from [`GlyphSet::g3`]. A DRCS character has no glyph in a
    /// glyph set and gives an empty one (REQ-RND-038).
    #[must_use]
    // Every cell line of every row looks its glyph up; inlining it into the
    // cell raster measured 12 percent faster whole-screen rendering
    // (REQ-TST-050, `tests/performance.rs`).
    #[allow(clippy::inline_always)]
    #[inline(always)]
    pub fn glyph(&self, character: CharRef) -> [u8; GLYPH_LINES] {
        if matches!(character.set, CharSet::Drcs { .. }) {
            return [0; GLYPH_LINES];
        }
        let unicode = to_unicode(character);
        let drawn = crate::charset::glyph_key(character);
        let base = self.lookup(drawn).or_else(|| self.lookup(unicode.base)).unwrap_or(PLACEHOLDER);
        let Some(mark) = unicode.combining.filter(|_| character.diacritic != DIACRITIC_NONE) else {
            return base;
        };
        if let Some(precomposed) = compose(unicode.base, mark).and_then(|c| self.lookup(c)) {
            return precomposed;
        }
        let spacing = spacing_mark(mark).and_then(|c| self.lookup(c)).unwrap_or([0; GLYPH_LINES]);
        let mut out = base;
        for (row, mark_row) in out.iter_mut().zip(spacing.iter()) {
            *row |= *mark_row;
        }
        out
    }
}

/// Each combining mark of the diacritical marks (REQ-CHR-008) and the
/// spacing character whose glyph is overlaid for it (decision E.26). Every
/// glyph set needs a glyph for each spacing character.
pub const SPACING_MARKS: [(char, char); 16] = [
    ('\u{0300}', '`'),
    ('\u{0301}', '\u{00B4}'),
    ('\u{0302}', '\u{02C6}'),
    ('\u{0303}', '\u{02DC}'),
    ('\u{0304}', '\u{00AF}'),
    ('\u{0306}', '\u{02D8}'),
    ('\u{0307}', '\u{02D9}'),
    ('\u{0308}', '\u{00A8}'),
    ('\u{030A}', '\u{02DA}'),
    ('\u{030B}', '\u{02DD}'),
    ('\u{030C}', '\u{02C7}'),
    ('\u{0323}', '.'),
    ('\u{0327}', '\u{00B8}'),
    ('\u{0328}', '\u{02DB}'),
    ('\u{0332}', '_'),
    // The Vietnamese G2 set's 4/C draws the hook above as U+02C0.
    ('\u{0309}', '\u{02C0}'),
];

/// The spacing form of a combining mark, whose glyph is overlaid.
fn spacing_mark(combining: char) -> Option<char> {
    SPACING_MARKS.iter().find(|(mark, _)| *mark == combining).map(|(_, spacing)| *spacing)
}

// The tests draw with the shipped glyph set.
#[cfg(all(test, feature = "bedstead"))]
#[allow(clippy::indexing_slicing, clippy::unwrap_used)]
mod tests {
    use super::*;
    use crate::charset::{CharSet, G0, G0Set};

    #[test]
    fn glyphs_are_sorted_and_unique() {
        let set = GlyphSet::bedstead();
        assert!(set.entries.windows(2).all(|pair| matches!(pair, [a, b] if a.code_point < b.code_point)));
    }

    /// REQ-RND-020: the glyph set is data; an empty set is allowed and
    /// finds nothing.
    #[test]
    fn set_size_and_empty_set() {
        static NONE: [GlyphEntry; 0] = [];
        let set = GlyphSet::bedstead();
        assert_eq!(set.len(), set.entries.len());
        assert!(!set.is_empty());
        let empty = GlyphSet::from_entries(&NONE, "empty");
        assert_eq!((empty.len(), empty.is_empty(), empty.provenance), (0, true, "empty"));
        assert_eq!(empty.lookup('A'), None);
        let latin = CharSet::G0(G0 { set: G0Set::Latin, national: None });
        assert_eq!(empty.glyph(CharRef::new(latin, b'A')), PLACEHOLDER, "REQ-CHR-004: a missing glyph is visible");
    }

    /// REQ-RND-014, decision E.26: every one of the fifteen G2 column 4
    /// marks (Table 28, modes 10001 to 11111) has a spacing form that
    /// Bedstead draws, and with no precomposed letter the mark is overlaid.
    #[test]
    fn every_diacritic_overlays_its_spacing_form() {
        // The spacing form Unicode pairs with each combining mark, in mark
        // order 4/1 to 4/F: grave, acute, circumflex, tilde, macron, breve,
        // dot above, diaeresis, dot below, ring, cedilla, low line, double
        // acute, ogonek and caron.
        const SPACING: [char; 15] = [
            '`', '\u{B4}', '\u{2C6}', '\u{2DC}', '\u{AF}', '\u{2D8}', '\u{2D9}', '\u{A8}', '.', '\u{2DA}', '\u{B8}',
            '_', '\u{2DD}', '\u{2DB}', '\u{2C7}',
        ];
        let set = GlyphSet::bedstead();
        let latin = CharSet::G0(G0 { set: G0Set::Latin, national: None });
        // "q" has no precomposed form with any of the marks.
        let base = set.lookup('q').unwrap();
        for (mark, &spacing) in (1u8..).zip(&SPACING) {
            let character = CharRef { diacritic: mark, ..CharRef::new(latin, b'q') };
            let combining = to_unicode(character).combining.unwrap();
            assert_eq!(spacing_mark(combining), Some(spacing), "mark {mark}");
            assert_eq!(compose('q', combining), None);
            let mark_rows = set.lookup(spacing).unwrap();
            assert_ne!(mark_rows, [0; GLYPH_LINES], "mark {mark} draws something");
            let overlay: [u8; GLYPH_LINES] = core::array::from_fn(|row| base[row] | mark_rows[row]);
            assert_eq!(set.glyph(character), overlay, "mark {mark}");
        }
        // A combining character outside the fifteen has no spacing form.
        assert_eq!(spacing_mark('\u{0305}'), None);
        assert_eq!(spacing_mark('a'), None);
    }

    /// REQ-RND-014, decision E.26: a precomposed glyph when the set has
    /// one, otherwise the spacing mark's glyph overlaid on the base.
    #[test]
    fn diacritics_use_the_precomposed_glyph_or_an_overlay() {
        const BASE: [u8; GLYPH_LINES] = [0, 0, 0x0E, 0x11, 0x1F, 0x10, 0x0E, 0, 0];
        const MARK: [u8; GLYPH_LINES] = [0x02, 0x04, 0, 0, 0, 0, 0, 0, 0];
        // Deliberately unlike the overlay, so the test tells them apart.
        const PRECOMPOSED: [u8; GLYPH_LINES] = [0x04, 0x08, 0x0E, 0x11, 0x1F, 0x10, 0x0F, 0, 0];
        static WITH_PRECOMPOSED: [GlyphEntry; 3] = [
            GlyphEntry { code_point: 'e' as u32, rows: BASE },
            GlyphEntry { code_point: '\u{B4}' as u32, rows: MARK },
            GlyphEntry { code_point: '\u{E9}' as u32, rows: PRECOMPOSED },
        ];
        static OVERLAY_ONLY: [GlyphEntry; 2] =
            [GlyphEntry { code_point: 'e' as u32, rows: BASE }, GlyphEntry { code_point: '\u{B4}' as u32, rows: MARK }];
        let latin = CharSet::G0(G0 { set: G0Set::Latin, national: None });
        // Diacritic 2 is the acute accent (Table 28, mode 10010).
        let character = CharRef { diacritic: 2, ..CharRef::new(latin, b'e') };
        assert_eq!(GlyphSet::from_entries(&WITH_PRECOMPOSED, "test").glyph(character), PRECOMPOSED);
        let overlay: [u8; GLYPH_LINES] = core::array::from_fn(|row| BASE[row] | MARK[row]);
        assert_eq!(GlyphSet::from_entries(&OVERLAY_ONLY, "test").glyph(character), overlay);
    }
}
